local function C_4()
	local script = LMG2L["LocalScript_4"];
	local button = script.Parent	

	button.MouseButton1Click:Connect(function()	
	    print("Decal spam çalıştı")	

	    for i = 1, 10 do	
	        local img = Instance.new("ImageLabel")	
	        img.Parent = button.Parent  -- sadece sen göresin diye aynı frame’e	
	        img.Size = UDim2.new(0, 100, 0, 100)	
	        img.Position = UDim2.new(math.random(), 0, math.random(), 0)	
	        img.BackgroundTransparency = 1	
	        img.Image = "rbxassetid://258128463"	

	        task.delay(1, function()	
	            img:Destroy()	
	        end)	

	        task.wait(0.05)	
	    end	
	end)	
end;
task.spawn(C_4);
-- Players.Esilap74.PlayerGui.MyOnlyGui...ParticleContainer.ParticleLoader
local function C_a()
	local script = LMG2L["ParticleLoader_a"];
	local player = game.Players.LocalPlayer	
	local button = script.Parent	

	button.MouseButton1Click:Connect(function()	
	    local char = player.Character or player.CharacterAdded:Wait()	
	    local head = char:FindFirstChild("Head")	
	    if not head then return end	

	    -- Particle oluştur	
	    local particle = Instance.new("ParticleEmitter")	
	    particle.Parent = head	

	    -- Ayarlar	
	    particle.Rate = 100	
	    particle.Speed = NumberRange.new(5,10)	
	    particle.Lifetime = NumberRange.new(1,2)	
	    particle.Size = NumberSequence.new(1)	
	    particle.Texture = "rbxassetid://258128463" -- güzel bir sparkle particle	
	    particle.Color = ColorSequence.new(Color3.fromRGB(255, 100, 100))	

	    -- 3 saniye sonra silinsin	
	    task.delay(3, function()	
	        particle:Destroy()	
	    end)	

	    print("Particle açıldı!")	
	end)	
end;
task.spawn(C_a);
-- Players.Esilap74.PlayerGui.MyOnlyGui.TextButton.LocalScript
local function C_d()
	local script = LMG2L["LocalScript_d"];
	local button = script.Parent	
	local player = game.Players.LocalPlayer	

	button.MouseButton1Click:Connect(function()	
	    local char = player.Character or player.CharacterAdded:Wait()	
	    local hrp = char:WaitForChild("HumanoidRootPart")	

	    -- Eski efekt var mı?	
	    if hrp:FindFirstChild("ElectricAura") then	
	        hrp.ElectricAura:Destroy()	
	    end	

	    -- Particle Emitter	
	    local emitter = Instance.new("ParticleEmitter")	
	    emitter.Name = "ElectricAura"	
	    emitter.Parent = hrp	

	    emitter.Texture = "rbxassetid://258128463" -- elektrik efekti	
	    emitter.Rate = 40	
	    emitter.Speed = NumberRange.new(2, 5)	
	    emitter.Rotation = NumberRange.new(0, 360)	
	    emitter.RotSpeed = NumberRange.new(20, 40)	
	    emitter.Lifetime = NumberRange.new(0.3, 0.7)	
	    emitter.SpreadAngle = Vector2.new(360, 360)	
	    emitter.LightEmission = 1	
	    emitter.Size = NumberSequence.new({	
	        NumberSequenceKeypoint.new(0, 0.6),	
	        NumberSequenceKeypoint.new(1, 0.1)	
	    })	

	    print("⚡ Elektrik Aura açıldı!")	
	end)	
end;
task.spawn(C_d);

